mapper.select:
SELECT 
FROM knowledge_document WHERE  AND document_id=#{id}
FOR UPDATE

SELECT candidate_id,revision,tenant_id,owner_id,base_revision,display_name,content_type,size_bytes,content_hash,
    source_bucket,source_key,text_body,required_text_json,content_digest,created_at
FROM knowledge_candidate_revision WHERE  AND candidate_id=#{id} AND revision=#{revision}

SELECT EXISTS (SELECT 1 FROM knowledge_chunk WHERE tenant_id=#{caller.tenantId} AND owner_id=#{caller.userId}
    AND document_id=#{publication.documentId} AND document_version=#{publication.version} AND job_id=#{publication.jobId}
    AND batch_digest=#{publication.batchDigest} AND LOCATE(CAST(#{text} AS BINARY),CAST(text AS BINARY)) > 0)
